package com.xxsx.earthonminecraft;

import net.minecraft.core.BlockPos;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;

/**
 * Holds the {@link DepositReserve} for one lode block.
 *
 * <p>Lode blocks are generated by worldgen as plain blocks, so this entity is attached lazily:
 * the first time anything asks about the reserve, a full one is created from the spec's
 * {@code capacity} for that lode. That keeps chunks that were generated before this feature
 * existed working without a migration.</p>
 */
public class DepositBlockEntity extends BlockEntity {
    private static final String LODE_KEY = "Lode";
    private static final String REMAINING_KEY = "Remaining";
    private static final String CAPACITY_KEY = "Capacity";

    private DepositReserve reserve;

    public DepositBlockEntity(BlockPos pos, BlockState state) {
        super(EarthOnMinecraft.DEPOSIT_BLOCK_ENTITY.get(), pos, state);
    }

    /** The reserve, created at full capacity on first access. */
    public DepositReserve reserve() {
        if (reserve == null) {
            Identifier lode = DepositSpec.lodeFor(getBlockState().getBlock());
            int capacity = DepositSpec.capacityFor(lode);
            reserve = DepositReserve.fresh(lode, capacity);
        }
        return reserve;
    }

    /** Marks the block entity dirty so the reserve is written back on save. */
    public void syncReserve() {
        setChanged();
    }

    @Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        DepositReserve current = reserve();
        output.store(LODE_KEY, Identifier.CODEC, current.lodeId());
        output.putInt(REMAINING_KEY, current.remaining());
        output.putInt(CAPACITY_KEY, current.capacity());
    }

    @Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        Identifier lode = input.read(LODE_KEY, Identifier.CODEC).orElse(null);
        if (lode == null) {
            reserve = null;
            return;
        }
        int capacity = input.getIntOr(CAPACITY_KEY, DepositSpec.capacityFor(lode));
        int remaining = input.getIntOr(REMAINING_KEY, capacity);
        reserve = new DepositReserve(lode, remaining, capacity);
    }
}
